import{_ as r,a0 as o,w as p,s as u,ao as a,I as t,x as l,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点 | LCTT x X-CMD","titleTemplate":false,"description":"新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210815 7 New Features in the Newly Released Debian 11 ‘Bullseye- Linux Distro","title":"新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点","tag":"202108","desc":""},"relativePath":"202108/20210815 7 New Features in the Newly Released Debian 11 ‘Bullseye- Linux Distro.md","filePath":"[post].md"}'),d={name:"202108/20210815 7 New Features in the Newly Released Debian 11 ‘Bullseye- Linux Distro.md"};function b(m,e,f,x,w,T){const i=o("Link");return p(),u("div",null,[e[31]||(e[31]=a('<h1 id="新发布的-debian-11-bullseye-linux-发行版的-7-大亮点" tabindex="-1">新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点 <a class="header-anchor" href="#新发布的-debian-11-bullseye-linux-发行版的-7-大亮点" aria-label="Permalink to “新发布的 Debian 11 “Bullseye” Linux 发行版的 7 大亮点”">​</a></h1><blockquote><p>这个最新发布的通用操作系统已经来到。</p></blockquote><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/08/debian-11-features.png?w=1200&amp;ssl=1" alt=""></p><p>期待已久的代号为 “Bullseye” 的 Debian 11 版本在经过两年的开发后终于来了。该版本将在未来五年内得到支持，就像任何其他的 Debian 稳定版版本一样。</p><p>感到兴奋吗？让我们来看看 Debian 11 的新内容。</p><h3 id="_1、新主题" tabindex="-1">1、新主题 <a class="header-anchor" href="#_1、新主题" aria-label="Permalink to “1、新主题”">​</a></h3>',6)),t("p",null,[e[1]||(e[1]=l("Debian 11 带有一个新的 “Homeworld” 主题。它的灵感来自 ",-1)),s(i,{href:"https://mymodernmet.com/what-is-bauhaus-art-movement/"},{default:n(()=>[...e[0]||(e[0]=[l("包豪斯运动",-1)])]),_:1}),e[2]||(e[2]=l("，这是一种 20 世纪初诞生于德国的艺术风格，其特点是对建筑和设计的独特处理。",-1))]),e[32]||(e[32]=a('<p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/08/homeworld_desktop.png?resize=1568%2C882&amp;ssl=1" alt="Debian 11 的默认壁纸"></p><p>在 Debian 11 中，无论是在登录界面、安装程序还是 Grub 菜单上，你都会看到这个主题。</p><p><img src="https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2021/08/homeworld_grub.png?w=640&amp;ssl=1" alt="Grub 屏幕"></p><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2021/08/homeworld_installer.png?w=800&amp;ssl=1" alt="安装程序"></p><p><img src="https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2021/08/homeworld_login.png?resize=1568%2C882&amp;ssl=1" alt="登录屏幕"></p><h3 id="_2、较新版本的桌面环境" tabindex="-1">2、较新版本的桌面环境 <a class="header-anchor" href="#_2、较新版本的桌面环境" aria-label="Permalink to “2、较新版本的桌面环境”">​</a></h3><p>Debian 11 包含了它所提供的桌面变体的较新版本：</p><ul><li>GNOME 3.38</li><li>KDE Plasma 5.20</li><li>LXDE 11</li><li>LXQt 0.16</li><li>MATE 1.24</li><li>Xfce 4.16</li></ul><p>如果你使用 Fedora 或 Arch/Manjaro 等先锐发行版，你可能会觉得很奇怪。但就是这样。Debian 更倾向于稳定，因此桌面环境的版本不是最新的。当然，它们与之前的 Debian 稳定版相比，还是比较新的。</p><h3 id="_3、软件包更新" tabindex="-1">3、软件包更新 <a class="header-anchor" href="#_3、软件包更新" aria-label="Permalink to “3、软件包更新”">​</a></h3><p>Debian 已经更新了它的软件包库。Debian 11 包括了多达 11294 个新软件包，软件包总数多达 59551 个。42821 个软件包有了新的版本。删除了 9519 个软件包。</p><p>也就是说你应该会看到像 LibreOffice、Emacs、GIMP 以及各种服务器和编程相关工具等流行应用程序的新版本。</p><h3 id="_4、linux-内核-5-10-lts" tabindex="-1">4、Linux 内核 5.10 LTS <a class="header-anchor" href="#_4、linux-内核-5-10-lts" aria-label="Permalink to “4、Linux 内核 5.10 LTS”">​</a></h3>',13)),t("p",null,[e[4]||(e[4]=l("Debian 11 带有 ",-1)),s(i,{href:"https://news.itsfoss.com/kernel-5-10-release/"},{default:n(()=>[...e[3]||(e[3]=[l("Linux 5.10 内核，这是一个长期支持（LTS）版本",-1)])]),_:1}),e[5]||(e[5]=l("。Debian 10 Buster 在发布时使用的是 Linux 4.19 内核。",-1))]),e[33]||(e[33]=a('<p>一个新的内核显然意味着对硬件有更好的支持，特别是较新的硬件以及性能的改进。</p><h3 id="_5、打印机和扫描器的改进" tabindex="-1">5、打印机和扫描器的改进 <a class="header-anchor" href="#_5、打印机和扫描器的改进" aria-label="Permalink to “5、打印机和扫描器的改进”">​</a></h3><p>Debian 11 带来了新的软件包 ipp-usb。它使用了许多现代打印机所支持的供应商中立的 IPP-over-USB 协议。这意味着许多较新的打印机将被 Debian 11 所支持，而不需要驱动程序。</p><p>同样地，SANE 无驱动后端可以让你轻松使用扫描仪。</p><h3 id="_6、支持-exfat" tabindex="-1">6、支持 exFAT <a class="header-anchor" href="#_6、支持-exfat" aria-label="Permalink to “6、支持 exFAT”">​</a></h3><p>你不再需要使用 exfat-fuse 包来挂载 exFAT 文件系统。借助 Linux 5.10 内核，Debian 11 已经支持 exFAT 文件系统，并且默认使用它来挂载 exFAT 文件系统。</p><h3 id="_7、仍然支持-32-位" tabindex="-1">7、仍然支持 32 位 <a class="header-anchor" href="#_7、仍然支持-32-位" aria-label="Permalink to “7、仍然支持 32 位”">​</a></h3>',7)),t("p",null,[e[7]||(e[7]=l("这算是一个功能吗？考虑到现在只有 ",-1)),s(i,{href:"https://itsfoss.com/32-bit-linux-distributions/"},{default:n(()=>[...e[6]||(e[6]=[l("少数几个 Linux 发行版支持 32 位架构",-1)])]),_:1}),e[8]||(e[8]=l("，我觉得是。",-1))]),e[34]||(e[34]=a('<p>除了 32 位和 64 位 PC，Debian 11 还支持 64 位 ARM（arm64）、ARM EABI（armel）、ARMv7（EABI hard-float ABI，armhf）、小端 MIPS（mipsel）、64 位小端 MIPS（mips64el）、64 位小端 PowerPC（ppc64el）和 IBM System z（s390x）。</p><p>现在你知道为什么它被称为“通用操作系统”了吧。 🙂</p><h3 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to “其他变化”">​</a></h3><p>在这个版本中还有一些变化：</p><ul><li>Systemd 默认使用控制组 v2（cgroupv2）。</li><li>针对中文、日文、韩文和其他许多语言的新 Fcitx 5 输入法。</li><li>Systemd 日记日志默认为持久性的。</li><li>一个新的打开命令，可以用某个应用程序（GUI 或 CLI）从命令行自动打开文件。</li><li>本地系统账户的密码散列现在默认使用 yescrypt 而不是 SHA-512 来提高安全性。</li></ul>',5)),t("p",null,[e[10]||(e[10]=l("更多信息可以在 ",-1)),s(i,{href:"https://www.debian.org/releases/bullseye/amd64/release-notes/ch-whats-new.en.html"},{default:n(()=>[...e[9]||(e[9]=[l("官方发布说明",-1)])]),_:1}),e[11]||(e[11]=l(" 中找到。",-1))]),e[35]||(e[35]=t("h3",{id:"获取-debian-11",tabindex:"-1"},[l("获取 Debian 11 "),t("a",{class:"header-anchor",href:"#获取-debian-11","aria-label":"Permalink to “获取 Debian 11”"},"​")],-1)),e[36]||(e[36]=t("p",null,"Debian 11 可以从其网站下载。只要前往该网站并从那里获得 ISO。",-1)),t("ul",null,[t("li",null,[s(i,{href:"https://www.debian.org/"},{default:n(()=>[...e[12]||(e[12]=[l("下载 Debian",-1)])]),_:1})])]),t("p",null,[e[14]||(e[14]=l("如果你已经在使用 Debian 10，你可以 ",-1)),s(i,{href:"https://www.debian.org/releases/bullseye/amd64/release-notes/ch-upgrading.en.html"},{default:n(()=>[...e[13]||(e[13]=[l("通过改变你的源列表轻松升级到 Debian 11",-1)])]),_:1}),e[15]||(e[15]=l(" 。",-1))]),e[37]||(e[37]=t("p",null,"享受最新和最棒的通用操作系统吧。🙂",-1)),e[38]||(e[38]=t("hr",null,null,-1)),t("p",null,[e[17]||(e[17]=l("via: ",-1)),s(i,{href:"https://news.itsfoss.com/debian-11-feature/"},{default:n(()=>[...e[16]||(e[16]=[l("https://news.itsfoss.com/debian-11-feature/",-1)])]),_:1})]),t("p",null,[e[22]||(e[22]=l("作者：",-1)),s(i,{href:"https://news.itsfoss.com/author/root/"},{default:n(()=>[...e[18]||(e[18]=[l("Abhishek",-1)])]),_:1}),e[23]||(e[23]=l(" 选题：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[19]||(e[19]=[l("lujun9972",-1)])]),_:1}),e[24]||(e[24]=l(" 译者：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[20]||(e[20]=[l("wxy",-1)])]),_:1}),e[25]||(e[25]=l(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[21]||(e[21]=[l("wxy",-1)])]),_:1})]),t("p",null,[e[28]||(e[28]=l("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[26]||(e[26]=[l("LCTT",-1)])]),_:1}),e[29]||(e[29]=l(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:n(()=>[...e[27]||(e[27]=[l("Linux中国",-1)])]),_:1}),e[30]||(e[30]=l(" 荣誉推出",-1))])])}const y=r(d,[["render",b]]);export{L as __pageData,y as default};
